	bs.Append([]byte("github.com"))
	bs.Append([]byte("/OpenList"))
	bs.Append([]byte("Team/?"))
	b := []byte("OpenList")
	off := bs.Size() - 1
	_ = bs.GrowTo(off + int64(len(b)))
	_, _ = bs.WriteAt(b, off)

	tests := []struct {
		name  string
		b     *hybrid_cache.BufferStore
		args  args
		check func(a args, n int, err error) error
	}{
		{
			name: "readAt len 10 offset 0",
			b:    bs,
			args: args{
				p:   make([]byte, 10),
				off: 0,
			},
			check: func(a args, n int, err error) error {
				if n != len(a.p) {
					return errors.New("read length not match")
				}
				if string(a.p) != "github.com" {
					return errors.New("read content not match")
				}
				if err != nil {
					return err
				}
				return nil
			},
		},
		{
			name: "readAt len 12 offset 11",
			b:    bs,
			args: args{
				p:   make([]byte, 12),
				off: 11,
			},
			check: func(a args, n int, err error) error {
				if n != len(a.p) {
					return errors.New("read length not match")
				}
				if string(a.p) != "OpenListTeam" {
					return errors.New("read content not match")
				}
				if err != nil {
					return err
				}
				return nil
			},
		},
		{
			name: "readAt len 50 offset 24",
			b:    bs,
			args: args{
				p:   make([]byte, 50),
				off: 24,
			},
			check: func(a args, n int, err error) error {
				if n != int(bs.Size()-a.off) {
					return errors.New("read length not match")
				}
				if string(a.p[:n]) != "OpenList" {
					return errors.New("read content not match")
				}
				if err != io.EOF {
					return errors.New("expect eof")
				}
				return nil
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := tt.b.ReadAt(tt.args.p, tt.args.off)
			if err := tt.check(tt.args, got, err); err != nil {
				t.Errorf("BufferStore.ReadAt() error = %v", err)
			}
		})
	}
}

package hybrid_cache_test

import (
	"bytes"
	"errors"
	"io"
	"os"
	"reflect"
	"testing"

	"github.com/OpenListTeam/OpenList/v4/internal/conf"
	"github.com/OpenListTeam/OpenList/v4/internal/hybrid_cache"
)

func TestFile(t *testing.T) {
	f, err := os.CreateTemp("", "writeat-*")
	if err != nil {
		t.Error(err)
		return
	}
	defer os.Remove(f.Name())
	defer f.Close()
	t.Run("ReadAt", func(t *testing.T) {
		_, err := f.ReadAt(make([]byte, 1), 20)
		if err != nil && !errors.Is(err, io.EOF) {
			t.Error(err)
		}
	})
	t.Run("WriteAt", func(t *testing.T) {
		n, err := f.WriteAt([]byte("abc"), 20)
		if err != nil {
			t.Errorf("write n=%d err=%v", n, err)
			return
		}
		stat, err := f.Stat()
		if err != nil {
			t.Errorf("stat err=%v", err)
			return
		}
		if stat.Size() != 23 {
			t.Fatalf("unexpected size: got %d want 23", stat.Size())
		}

		b := make([]byte, stat.Size())
		rn, rerr := f.ReadAt(b, 0)
		if rn != len(b) || rerr != nil {
			t.Fatalf("read n=%d err=%v", rn, rerr)
		}
		want := append(make([]byte, 20), []byte("abc")...)
		if !reflect.DeepEqual(b, want) {
			t.Fatalf("unexpected content: got %v want %v", b, want)
		}
	})
}

func TestMultiFileCache(t *testing.T) {
	prevConf := conf.Conf
	t.Cleanup(func() {
		conf.Conf = prevConf
	})
	conf.Conf = &conf.Config{}
	f := hybrid_cache.MultiFileStore{}
	defer f.Close()
	t.Run("ReadAt", func(t *testing.T) {
		_, err := f.ReadAt(make([]byte, 1), 20)
		if err != nil && !errors.Is(err, io.EOF) {
			t.Error(err)
		}
	})
	t.Run("WriteAt", func(t *testing.T) {
		err := f.GrowTo(15)
		if err != nil {
			t.Errorf("truncate err=%v", err)
			return
		}
		n, err := f.WriteAt([]byte("abc"), 10)
		if err != nil {
			t.Errorf("write n=%d err=%v", n, err)
			return
		}

		err = f.GrowTo(30)
		if err != nil {
			t.Errorf("truncate err=%v", err)
			return
		}
		_, _ = f.WriteAt([]byte("123"), 15)

		b := append(make([]byte, 17), []byte("def")...)
		b[0] = 'a'
		rn, rerr := f.ReadAt(b, 8)
		if rn != len(b) || rerr != nil {
			t.Fatalf("read n=%d err=%v", rn, rerr)
		}
		want := []byte{0, 0, 'a', 'b', 'c', 0, 0, '1', '2', '3'}
		want = append(want, make([]byte, 10)...)
		if !bytes.Equal(b, want) {
			t.Fatalf("unexpected content: got %v want %v", b, want)
		}
	})
}
